        before_ = seen_()
        c_, o_, e_ = _tool_run(HERE / "shoalmark.py", root, *(["--init"] if kind == "init" else []))
        after_ = seen_()
        g_ = dict(code=c_, out=o_.strip(), err=e_.strip(), same=before_ == after_, made=sorted(set(after_[1]) - set(before_[1])))
        rm_git(root)
