        git(root, "init", "-q"); run(root, "--init", "--key", "msr"); tracker(root, "MSR-001"); git(root, "add", "-A"); git(root, "commit", "-qm", "base"); fm.configure(HERE)
        git(root, "worktree", "add", "-q", str(base / "gone"), "-b", "gone")
