    for k_, v_ in (("user.name", "holgo"), ("user.email", "h@x"), ("commit.gpgsign", "false"), ("core.hooksPath", str(root / ".git" / "hooks"))):
        git(root, "config", k_, v_)
    git(root, "remote", "add", "origin", str(base / "origin.git"))
