    (root / "merge-msg").write_text("Merge side/import\n"); codem_, _o, errm_ = run(root, "--commit-msg", str(root / "merge-msg"))
    git(root, "merge", "--abort"); (root / "merge-msg").unlink(); git(root, "switch", "-q", "main")
